def epsilon_greedy(n_arms, pull, steps, eps=0.1):
    count = [0] * n_arms
    value = [0.0] * n_arms  # 행동별 평균 보상 추정치
    for t in range(steps):
        if rand() < eps:
            a = rand_int(n_arms)  # 탐험: 무작위 행동
        else:
            a = value.index(max(value))  # 활용: 현재 최선
        r = pull(a)
        count[a] += 1
        value[a] += (r - value[a]) / count[a]  # 증분 평균
    return value

extent.pseudocode:
def lookup(extents, lblock):
    # extents: (논리 시작, 물리 시작, 길이), 논리 시작 순
    lo, hi = 0, len(extents) - 1
    while lo <= hi:  # 이진 탐색
        mid = (lo + hi) // 2
        ls, ps, n = extents[mid]
        if lblock < ls:
            hi = mid - 1
        elif lblock >= ls + n:
            lo = mid + 1
        else:
            return ps + (lblock - ls)  # 구간 내 오프셋
    return None  # 할당되지 않은 구멍(hole)

