# 추출 전: 한 메서드에 여러 의도가 섞임
def print_owing(invoice):
    print('***** 고객 청구서 *****')
    outstanding = 0
    for o in invoice.orders:
        outstanding += o.amount
    print('고객:', invoice.customer)
    print('미지급액:', outstanding)

# 추출 후: 조각마다 이름으로 의도 표현
def print_owing(invoice):
    print_banner()
    outstanding = calc_outstanding(invoice)  # 변경 값은 반환
    print_details(invoice, outstanding)  # 읽기 값은 인자로

def print_banner():
    print('***** 고객 청구서 *****')

def calc_outstanding(invoice):
    return sum(o.amount for o in invoice.orders)

def print_details(invoice, outstanding):
    print('고객:', invoice.customer)
    print('미지급액:', outstanding)
